INSERT INTO categories (id, slug, name, image, description, display_order, active) VALUES
('cat-handles', 'handles', 'Handles', '/products/matte-black-gold-banded-tbar-handle.jpg', 'Modern cabinet bar handles, profile pulls, T-bars, and luxury wardrobe handles.', 1, true),
('cat-knobs', 'knobs', 'Knobs', '/products/solid-polished-ball-knob.jpg', 'Brass, matte black, crystal, and stainless steel drawer and dresser knobs.', 2, true),
('cat-doors', 'doors', 'Doors & Security Doors', '/products/luxury-mahogany-flush-door-silver-inlays.jpg', 'Architectural interior flush doors, security doors, and double entrance doors with complete matching frames and architraves.', 3, true),
('cat-hinges', 'hinges', 'Hinges', 'https://images.unsplash.com/photo-1538688525198-9b88f6f53126?w=400&h=300&fit=crop&q=80', 'Hydraulic soft-close cabinet hinges, concealed 3D hinges, and heavy-duty pivot hinges.', 4, true),
('cat-locks', 'locks', 'Locks', 'https://images.unsplash.com/photo-1558002038-1055907df827?w=400&h=300&fit=crop&q=80', 'Drawer locks, wardrobe cam locks, digital keypad locks, and central locking bars.', 5, true),
('cat-fittings', 'furniture-fittings', 'Furniture Fittings', '/products/magic-corner-kitchen-basket.jpg', 'Telescopic drawer slides, soft-close pantry larder units, corner pullouts, and spice racks.', 6, true),
('cat-accessories', 'other-accessories', 'Other Accessories', '/products/luxury-wardrobe-jewelry-tray.jpg', 'Luxury wardrobe jewelry trays, laundry pull-out baskets, cutlery dividers, and caster wheels.', 7, true),
('cat-appliances', 'kitchen-appliances', 'Kitchen Appliances', '/products/hippont-90cm-flat-heat-extractor.jpg', 'Built-in gas hobs, electric cooktops, digital heat extractors, range hoods, and built-in microwaves.', 8, true)
INSERT INTO products (id, slug, name, sku, category_id, category_name, category_slug, description, price_kobo, wholesale_price_kobo, wholesale_min_qty, wholesale_enabled, retail_enabled, images, stock_quantity, reserved_quantity, low_stock_threshold, specs, active, featured) VALUES
('prd-hdl-01', 'luxury-black-gold-geometric-cabinet-pull-handle', 'Luxury Black & Gold Geometric Cabinet Pull Handle', 'HDL-BLK-GLD-GEO', 'cat-handles', 'Handles', 'handles', 'Contemporary dual-tone cabinet pull handle with lustrous gold accents and matte black inlay. Built for luxury wardrobes and bespoke modern kitchen cabinetry.', 450000, 350000, 20, true, true, '["/products/luxury-gold-black-geometric-handle.jpg"]'::jsonb, 150, 0, 15, '[{"label":"Material","value":"Solid Zinc Alloy"},{"label":"Finish","value":"Electroplated Gold & Matte Black"},{"label":"Hole Spacing","value":"128mm / 160mm / 192mm"},{"label":"Application","value":"Kitchen Cabinets, Wardrobes, Drawers"}]'::jsonb, true, true),
('prd-hdl-02', 'matte-black-gold-banded-tbar-cabinet-handle', 'Matte Black & Gold Banded T-Bar Cabinet Handle', 'HDL-BLK-GLD-TBR', 'cat-handles', 'Handles', 'handles', 'Refined cylindrical T-bar handle featuring gold ring accents on a rich matte black bar. Available in multiple lengths and matching single knobs.', 420000, 320000, 20, true, true, '["/products/matte-black-gold-banded-tbar-handle.jpg"]'::jsonb, 180, 0, 20, '[{"label":"Material","value":"Stainless Steel & Solid Brass Rings"},{"label":"Finish","value":"Matte Black with Polished Gold Rings"},{"label":"Hole Spacing","value":"96mm, 128mm, 192mm, 256mm"},{"label":"Application","value":"Cabinetry, Cupboards, Wardrobes"}]'::jsonb, true, true),
('prd-hdl-03', 'matte-black-modern-bow-bridge-cabinet-handle', 'Matte Black Modern Bow Bridge Cabinet Handle', 'HDL-BLK-BOW01', 'cat-handles', 'Handles', 'handles', 'Ergonomic bridge-style arched cabinet handle with flared mounting feet. Clean minimalist design suitable for contemporary kitchens and furniture.', 380000, 290000, 25, true, true, '["/products/matte-black-bow-bridge-handle.jpg"]'::jsonb, 200, 0, 25, '[{"label":"Material","value":"Die-cast Aluminum Alloy"},{"label":"Finish","value":"Anodized Matte Black"},{"label":"Hole Spacing","value":"128mm, 160mm, 224mm"},{"label":"Application","value":"Kitchen drawers, Wardrobes"}]'::jsonb, true, false),
('prd-hdl-04', 'brushed-stainless-steel-heavy-duty-modern-bar-handle', 'Brushed Stainless Steel Heavy-Duty Modern Bar Handle', 'HDL-SS-BAR01', 'cat-handles', 'Handles', 'handles', 'Corrosion-resistant brushed stainless steel round bar pull handles with solid square standoffs. High durability for heavy traffic cabinets.', 350000, 260000, 25, true, true, '["/products/brushed-stainless-steel-bar-handle.jpg"]'::jsonb, 220, 0, 20, '[{"label":"Material","value":"Grade 304 Stainless Steel"},{"label":"Finish","value":"Satin Brushed Chrome"},{"label":"Hole Spacing","value":"128mm, 160mm, 192mm, 320mm"},{"label":"Durability","value":"Rustproof, Commercial Grade"}]'::jsonb, true, false),
('prd-hdl-05', 'minimalist-aluminum-edge-profile-pull-handle', 'Minimalist Aluminum Edge Profile Pull Handle', 'HDL-EDG-PRF01', 'cat-handles', 'Handles', 'handles', 'Modern edge-mounted profile pull handle available in Brushed Gold and Matte Black. Mounts seamlessly on the top or side edge of doors for a sleek handleless look.', 390000, 295000, 20, true, true, '["/products/minimalist-edge-profile-pull-handle.jpg"]'::jsonb, 160, 0, 20, '[{"label":"Material","value":"Extruded Aluminum"},{"label":"Colors","value":"Brushed Champagne Gold & Matte Black"},{"label":"Lengths","value":"150mm, 200mm, 300mm, 400mm"},{"label":"Mounting","value":"Rear Screw Edge Fix"}]'::jsonb, true, true),
('prd-hdl-06', 'matte-black-architectural-tbar-cabinet-pull-knob', 'Matte Black Architectural T-Bar Cabinet Pull & Knob', 'HDL-BLK-TBR02', 'cat-handles', 'Handles', 'handles', 'Bold square-profile matte black T-bar handle with solid square posts. Engineered for heavy kitchen pantry doors and vanity drawers.', 320000, 240000, 25, true, true, '["/products/matte-black-architectural-tbar-handle.jpg"]'::jsonb, 240, 0, 25, '[{"label":"Material","value":"Solid Aluminum Alloy"},{"label":"Finish","value":"Anodized Black Matte"},{"label":"Hole Spacing","value":"96mm, 128mm, 160mm, 192mm"},{"label":"Includes","value":"M4 Mounting Screws"}]'::jsonb, true, false),
('prd-hdl-07', 'matte-black-concealed-lip-edge-finger-pull-handle', 'Matte Black Concealed Lip Edge Finger Pull Handle', 'HDL-BLK-LIP01', 'cat-handles', 'Handles', 'handles', 'Low-profile continuous lip finger pull that slots neatly over cabinet door edges. Provides a clean seamless aesthetic without visible screw heads.', 360000, 270000, 25, true, true, '["/products/matte-black-concealed-lip-edge-pull.jpg"]'::jsonb, 190, 0, 20, '[{"label":"Material","value":"Precision Aluminum Extrusion"},{"label":"Finish","value":"Matte Black Powder Coat"},{"label":"Door Thickness","value":"Fits 18mm to 20mm panels"},{"label":"Application","value":"Modern Handleless Kitchens"}]'::jsonb, true, false),
('prd-knb-01', 'modern-oval-paperclip-drop-ring-drawer-knob', 'Modern Oval Paperclip Drop Ring Drawer Knob', 'KNB-OVL-PPC01', 'cat-knobs', 'Knobs', 'knobs', 'Creative dual-tone designer oval ring knob with gold frame and vibrant matte insert plates (Black, White, Orange, Silver). Perfect accent for luxury dressers.', 220000, 170000, 30, true, true, '["/products/modern-oval-paperclip-drawer-knob.jpg"]'::jsonb, 250, 0, 30, '[{"label":"Material","value":"Solid Brass & Zinc Inlay"},{"label":"Color Options","value":"Gold/Black, Gold/White, Gold/Orange, Chrome/Black"},{"label":"Mounting","value":"Single Hole Bolt"},{"label":"Application","value":"Wardrobes, Nightstands, Vanity Drawers"}]'::jsonb, true, true),
('prd-knb-02', 'solid-polished-spherical-ball-cabinet-knob', 'Solid Polished Spherical Ball Cabinet Knob', 'KNB-BAL-SLD01', 'cat-knobs', 'Knobs', 'knobs', 'Heavy solid spherical ball knob with mirror-polished reflective finish. Available in French Gold, Rose Gold, and Mirror Chrome.', 180000, 135000, 30, true, true, '["/products/solid-polished-ball-knob.jpg"]'::jsonb, 300, 0, 30, '[{"label":"Material","value":"Solid Brass Alloy"},{"label":"Diameter","value":"25mm / 30mm"},{"label":"Finish","value":"High Gloss Mirror Gold & Chrome"},{"label":"Application","value":"Cabinets, Bathroom Vanities, Sideboards"}]'::jsonb, true, false),
('prd-fit-01', 'magic-corner-kitchen-pull-out-blind-corner-organizer-basket', 'Magic Corner Kitchen Pull-Out Blind Corner Organizer Basket', 'FIT-CRN-001', 'cat-fittings', 'Furniture Fittings', 'furniture-fittings', 'Heavy-duty 2-tier magic corner mechanism with smooth soft-close sliding tracks. Pulls blind corner kitchen contents forward for effortless access.', 14500000, 12500000, 3, true, true, '["/products/magic-corner-kitchen-basket.jpg"]'::jsonb, 12, 0, 2, '[{"label":"Mechanism","value":"Synchronized Soft-Close Runner"},{"label":"Tray Material","value":"Tempered Smoked Glass & Carbon Steel"},{"label":"Cabinet Width","value":"Fits 900mm - 1000mm blind corner units"},{"label":"Load Capacity","value":"Up to 35kg total"}]'::jsonb, true, true),
('prd-fit-02', 'multi-tier-kitchen-tall-larder-tandem-pantry-pull-out-unit', 'Multi-Tier Kitchen Tall Larder / Tandem Pantry Pull-Out Unit', 'FIT-LDR-001', 'cat-fittings', 'Furniture Fittings', 'furniture-fittings', 'Tall pantry larder storage system with dual-action door trays and internal pull-out shelves. Maximizes vertical kitchen storage space.', 22000000, 19500000, 2, true, true, '["/products/tall-larder-pantry-unit.jpg"]'::jsonb, 10, 0, 2, '[{"label":"Height Range","value":"1850mm - 2150mm (Adjustable Frame)"},{"label":"Baskets","value":"6 Main Trays + 6 Door Baskets"},{"label":"Motion","value":"Heavy Duty Soft Close Damper"},{"label":"Load Rating","value":"70kg Total"}]'::jsonb, true, true),
('prd-fit-03', 'premium-glass-side-tall-pantry-pull-out-larder-unit', 'Premium Glass-Side Tall Pantry Pull-Out Larder Unit', 'FIT-LDR-002', 'cat-fittings', 'Furniture Fittings', 'furniture-fittings', 'High-end tall larder unit with transparent smoked glass side guards and non-slip mats. Full extension soft close slide mechanism.', 24000000, 21500000, 2, true, true, '["/products/tall-pantry-glass-pullout.jpg"]'::jsonb, 8, 0, 2, '[{"label":"Basket Sides","value":"Smoked Toughened Safety Glass"},{"label":"Slides","value":"Under-mount Heavy Duty Hydraulic Runners"},{"label":"Cabinet Width","value":"450mm / 600mm"},{"label":"Load Capacity","value":"80kg"}]'::jsonb, true, false),
('prd-fit-04', 'soft-close-tall-larder-swing-out-pantry-unit', 'Soft-Close Tall Larder Swing-Out Pantry Unit', 'FIT-LDR-003', 'cat-fittings', 'Furniture Fittings', 'furniture-fittings', 'Swing-out 180° revolving tall pantry system. When opened, inner baskets glide forward while door baskets pivot outward for full panoramic visibility.', 26000000, 23000000, 2, true, true, '["/products/tall-larder-swingout-pantry.jpg"]'::jsonb, 6, 0, 2, '[{"label":"Structure","value":"Anodized Grey Steel & Glass Baskets"},{"label":"Capacity","value":"12 Tier Storage (6 Door + 6 Inner)"},{"label":"Opening Angle","value":"110° to 180° swing"}]'::jsonb, true, false),
('prd-fit-05', 'heavy-duty-pull-down-elevator-upper-cabinet-spice-rack', 'Heavy-Duty Pull-Down Elevator Upper Cabinet Spice Rack', 'FIT-PLD-SPC01', 'cat-fittings', 'Furniture Fittings', 'furniture-fittings', 'Hydraulic counterbalanced pull-down storage basket for overhead wall cabinets. Lowers jars and spices directly into comfortable reaching height.', 8500000, 7200000, 3, true, true, '["/products/pulldown-elevator-spice-rack.jpg"]'::jsonb, 20, 0, 4, '[{"label":"Cabinet Width","value":"600mm / 800mm / 900mm wall cabinets"},{"label":"Mechanism","value":"Dual Gas-Spring Balanced Lift"},{"label":"Tiers","value":"2-Tier Stainless Steel with Front Guard"},{"label":"Weight Capacity","value":"15kg"}]'::jsonb, true, true),
('prd-fit-06', 'kitchen-under-counter-dish-plate-organizer-drawer-rack', 'Kitchen Under-Counter Dish & Plate Organizer Drawer Rack', 'FIT-KTC-DSH01', 'cat-fittings', 'Furniture Fittings', 'furniture-fittings', 'Pull-out base cabinet drawer basket designed with dedicated vertical slots for dinner plates, bowls, and cookware with drip drainage base.', 6800000, 5800000, 3, true, true, '["/products/kitchen-dish-plate-drawer-rack.jpg"]'::jsonb, 22, 0, 5, '[{"label":"Material","value":"Stainless Steel & Solid Polymer"},{"label":"Drawer Size","value":"Fits 800mm - 900mm wide drawers"},{"label":"Runner Type","value":"Undermount Soft-Close Slides"}]'::jsonb, true, false),
('prd-fit-07', 'heavy-duty-90-corner-cabinet-suspension-hanging-bracket-fittings', 'Heavy-Duty 90° Corner Cabinet Suspension Hanging Bracket Fittings', 'FIT-BRK-90DEG', 'cat-fittings', 'Furniture Fittings', 'furniture-fittings', 'Concealed steel corner brackets with snap-on decorative cover caps. Used for structural assembly and wall hanging of heavy kitchen and wardrobe cabinets.', 120000, 85000, 50, true, true, '["/products/corner-cabinet-suspension-bracket-fittings.jpg"]'::jsonb, 500, 0, 50, '[{"label":"Material","value":"Zinc Plated Steel with ABS Cover"},{"label":"Cap Colors","value":"Black, White, Grey, Brown"},{"label":"Angle","value":"90 Degree Precision"},{"label":"Application","value":"Cabinet Wall Hanging & Joint Support"}]'::jsonb, true, false),
('prd-acc-01', 'luxury-wardrobe-leather-jewelry-watch-organizer-drawer-tray', 'Luxury Wardrobe Leather Jewelry & Watch Organizer Drawer Tray', 'ACC-WRD-JWL01', 'cat-accessories', 'Other Accessories', 'other-accessories', 'Master closet organizer tray wrapped in premium grey micro-suede leather with custom compartments for watches, rings, sunglasses, and precious jewelry.', 4500000, 3800000, 5, true, true, '["/products/luxury-wardrobe-jewelry-tray.jpg"]'::jsonb, 25, 0, 5, '[{"label":"Exterior","value":"Hand-stitched Grey PU Leather"},{"label":"Interior","value":"Velvet Soft Cushion Dividers"},{"label":"Dimensions","value":"864mm x 450mm x 60mm (Customizable)"},{"label":"Application","value":"Wardrobe Island, Master Bedroom Dresser"}]'::jsonb, true, true),
('prd-acc-02', 'wardrobe-pull-out-woven-rattan-laundry-storage-basket', 'Wardrobe Pull-Out Woven Rattan Laundry & Storage Basket', 'ACC-WRD-BSK01', 'cat-accessories', 'Other Accessories', 'other-accessories', 'Breathable hand-woven rattan storage basket set into an aluminum pullout frame with concealed soft-close slide runners.', 5500000, 4600000, 4, true, true, '["/products/wardrobe-woven-rattan-basket.jpg"]'::jsonb, 30, 0, 5, '[{"label":"Basket","value":"Synthetic Breathable Rattan Weave"},{"label":"Frame","value":"Anodized Charcoal Aluminum"},{"label":"Cabinet Width","value":"600mm / 800mm / 900mm"},{"label":"Runners","value":"Full Extension Soft Close"}]'::jsonb, true, false),
('prd-acc-03', 'kitchen-cutlery-utensil-organizer-grey-abs-drawer-tray', 'Kitchen Cutlery & Utensil Organizer Grey ABS Drawer Tray', 'ACC-KTC-CTL01', 'cat-accessories', 'Other Accessories', 'other-accessories', 'Durable food-grade ABS cutlery organizer tray with molded compartments for spoons, knives, forks, and long cooking utensils.', 1850000, 1450000, 10, true, true, '["/products/kitchen-cutlery-tray-grey.jpg"]'::jsonb, 45, 0, 10, '[{"label":"Material","value":"High-Impact Food Grade ABS"},{"label":"Color","value":"Anthracite Metallic Grey"},{"label":"Size","value":"Fits 600mm - 900mm wide kitchen drawers"},{"label":"Maintenance","value":"Wipe Clean / Dishwasher Safe"}]'::jsonb, true, false),
('prd-app-01', 'hippont-90cm-slim-flat-kitchen-heat-extractor', 'HIPPONT 90cm Slim Flat Kitchen Heat Extractor', 'APP-HIP-EXT90', 'cat-appliances', 'Kitchen Appliances', 'kitchen-appliances', 'High suction 90cm flat kitchen heat extractor hood with digital touch control panel, multi-layer aluminum grease filters, and ultra-bright LED work lighting.', 12500000, 11500000, 2, true, true, '["/products/hippont-90cm-flat-heat-extractor.jpg"]'::jsonb, 15, 0, 3, '[{"label":"Brand","value":"HIPPONT"},{"label":"Size","value":"90cm Slim Profile"},{"label":"Control","value":"Digital Touch & Motion Sensor"},{"label":"Filter","value":"3x Washable Baffle Filters"},{"label":"Lighting","value":"High-efficiency LED Strip"}]'::jsonb, true, true),
('prd-app-02', 'hippont-5-burner-tempered-glass-built-in-cooktop-hob', 'HIPPONT 5-Burner Tempered Glass Built-In Cooktop Hob', 'APP-HIP-HOB05', 'cat-appliances', 'Kitchen Appliances', 'kitchen-appliances', 'Premium 5-burner gas cooktop with 8mm explosion-proof tempered black glass, heavy-duty cast iron pan supports, and automatic electric pulse ignition.', 13000000, 11800000, 2, true, true, '["/products/hippont-5-burner-glass-cooktop.jpg"]'::jsonb, 18, 0, 3, '[{"label":"Brand","value":"HIPPONT"},{"label":"Burners","value":"5 High-Efficiency Gas Burners (Triple Ring Wok)"},{"label":"Surface","value":"8mm Tempered Black Safety Glass"},{"label":"Supports","value":"Heavy Duty Cast Iron"},{"label":"Ignition","value":"Automatic Under-knob Electric Pulse"}]'::jsonb, true, true),
('prd-app-03', 'polystar-20l-built-in-microwave-pv-bd20bbl', 'POLYSTAR 20L Built-In Microwave with Frame Kit (PV-BD20BBL)', 'APP-PLY-MCW20', 'cat-appliances', 'Kitchen Appliances', 'kitchen-appliances', 'Polystar 20-Litre built-in microwave oven with integrated grill function, seamless trim frame kit, 700W microwave output, and 900W grill power input.', 18500000, 16500000, 2, true, true, '["/products/polystar-20l-builtin-microwave.jpg"]'::jsonb, 14, 0, 3, '[{"label":"Brand","value":"POLYSTAR (PV-BD20BBL)"},{"label":"Capacity","value":"20 Litres"},{"label":"Microwave Power","value":"700 Watts"},{"label":"Grill Power","value":"900 Watts"},{"label":"Control","value":"Digital Control with LED Display"}]'::jsonb, true, true),
('prd-app-04', 'polystar-4-burner-1-electric-built-in-gas-hob-pv-jyps4g1eb', 'POLYSTAR 4-Burner & 1 Electric Built-In Gas Hob (PV-JYPS4G1EB)', 'APP-PLY-HOB41', 'cat-appliances', 'Kitchen Appliances', 'kitchen-appliances', 'Dual-fuel hybrid built-in hob featuring 4 rapid gas burners and 1 rapid electric hotplate on an 8mm black stainless steel chassis with metal control knobs.', 17500000, 15500000, 2, true, true, '["/products/polystar-4b-1e-gas-hob.jpg"]'::jsonb, 16, 0, 3, '[{"label":"Brand","value":"POLYSTAR (PV-JYPS4G1EB)"},{"label":"Configuration","value":"4 Gas Burners + 1 Electric Hotplate"},{"label":"Material","value":"8mm Real Stainless Steel Black Finish"},{"label":"Knobs","value":"Heat-resistant Metal Knobs with BS Plug"}]'::jsonb, true, false),
('prd-app-05', 'polystar-90cm-digital-rangehood-voice-control-pv-td9110bvc', 'POLYSTAR 90cm Digital Rangehood with Voice Control (PV-TD9110BVC)', 'APP-PLY-RNG90', 'cat-appliances', 'Kitchen Appliances', 'kitchen-appliances', 'Smart kitchen rangehood with intelligent voice commands, infrared hand gesture control, pure copper motor, metal blower, and aluminum charcoal filters.', 19500000, 17500000, 2, true, true, '["/products/polystar-90cm-digital-rangehood.jpg"]'::jsonb, 12, 0, 2, '[{"label":"Brand","value":"POLYSTAR (PV-TD9110BVC)"},{"label":"Smart Tech","value":"Voice Control & Hand Wave Motion Sensor"},{"label":"Motor","value":"Heavy Duty 100% Pure Copper Motor"},{"label":"Filter","value":"Aluminum Charcoal Filter with Metal Blower"},{"label":"Lighting","value":"Tempered Glass with Energy-Saving LED"}]'::jsonb, true, true),
('prd-door-01', 'luxury-mahogany-flush-door-dual-silver-inlays', 'Luxury Mahogany Flush Door with Dual Silver Inlays & Full Frame', 'DOR-MHG-SLV2', 'cat-doors', 'Doors & Security Doors', 'doors', 'High-density solid-core mahogany wood-grain interior security door featuring precision horizontal brushed silver accent inlays, full matching architrave jamb casing, and mortise lever lockset compatibility. All standard and luxury height sizes available.', 10500000, 9200000, 3, true, true, '["/products/luxury-mahogany-flush-door-silver-inlays.jpg"]'::jsonb, 24, 0, 4, '[{"label":"Available Sizes","value":"800 x 2100mm, 800 x 2300mm, 900 x 2100mm, 900 x 2300mm, 1200 x 2100mm, 1200 x 2300mm"},{"label":"Finish","value":"Natural Mahogany Grain with Clear UV Protective Coat"},{"label":"Inlay Design","value":"Dual Brushed Silver Aluminium Horizontal Inlays"},{"label":"Frame & Architrave","value":"Full Matching Engineered Wood Frame & Casing Included"},{"label":"Core Type","value":"Solid Acoustic & Sound-Dampening Engineered Core"},{"label":"Application","value":"Master Bedroom, Office Suite, Luxury Apartment"}]'::jsonb, true, true),
('prd-door-02', 'executive-white-paneled-double-entrance-door-frosted-glass', 'Executive White Paneled Double Entrance Door with Frosted Glass', 'DOR-WHT-DBL-GLS', 'cat-doors', 'Doors & Security Doors', 'doors', 'Architectural 1.5-leaf mother-and-child double entrance door in pure satin white. Features tempered frosted glass grid lites for gentle natural illumination with full privacy, classic raised bottom panels, and wide ornamental corniced architraves.', 21500000, 19000000, 2, true, true, '["/products/executive-white-paneled-double-door-frosted-glass.jpg"]'::jsonb, 15, 0, 3, '[{"label":"Available Sizes","value":"800 x 2100mm, 800 x 2300mm, 900 x 2100mm, 900 x 2300mm, 1200 x 2100mm, 1200 x 2300mm"},{"label":"Door Style","value":"Unequal Double Leaf (Mother & Child) / Glazed Entrance"},{"label":"Glazing","value":"Dual-Layer Tempered Frosted Privacy Glass"},{"label":"Finish","value":"Waterproof Satin White Polyurethane Coat"},{"label":"Frame & Architrave","value":"Heavy-Duty Reinforced Door Jamb with Moulded Cornice Casing"},{"label":"Hardware Support","value":"Compatible with T-Bar Handles, Deadbolts & Pulls"}]'::jsonb, true, true),
('prd-door-03', 'contemporary-natural-oak-flush-door-geometric-black-inlays', 'Contemporary Natural Oak Flush Door with Geometric Black Inlays', 'DOR-OAK-BLK-GEO', 'cat-doors', 'Doors & Security Doors', 'doors', 'Modern Scandinavian-inspired interior flush door crafted with warm natural oak vertical grain veneer and CNC-machined geometric black groove lines. Includes matching seamless box-profile architrave casing.', 9800000, 8500000, 3, true, true, '["/products/contemporary-natural-oak-interior-door-grooves.jpg"]'::jsonb, 28, 0, 5, '[{"label":"Available Sizes","value":"800 x 2100mm, 800 x 2300mm, 900 x 2100mm, 900 x 2300mm, 1200 x 2100mm, 1200 x 2300mm"},{"label":"Veneer Finish","value":"Natural European White Oak Grain Finish"},{"label":"Inlay Design","value":"Precision Asymmetrical Black Grooved Architectural Lines"},{"label":"Frame Profile","value":"Full Concealed-Joint Architrave Frame System Included"},{"label":"Thickness","value":"45mm Heavy-Duty Solid Door Leaf"},{"label":"Recommended For","value":"Modern Living Rooms, Bedrooms, Commercial Executive Offices"}]'::jsonb, true, true),
('prd-door-04', 'architectural-matte-anthracite-flush-door-4-brushed-chrome-inlays', 'Architectural Matte Anthracite Flush Door with 4 Brushed Chrome Inlays', 'DOR-ANT-CHR4', 'cat-doors', 'Doors & Security Doors', 'doors', 'Ultra-modern luxury interior door in deep matte anthracite charcoal grey finish. Accented with 4 equidistant brushed chrome horizontal metal strips embedded flush into the door leaf, framed with matching charcoal architrave casing.', 11500000, 9800000, 3, true, true, '["/products/architectural-matte-anthracite-flush-door-chrome-strips.jpg"]'::jsonb, 20, 0, 4, '[{"label":"Available Sizes","value":"800 x 2100mm, 800 x 2300mm, 900 x 2100mm, 900 x 2300mm, 1200 x 2100mm, 1200 x 2300mm"},{"label":"Finish","value":"Anti-Fingerprint Matte Anthracite Charcoal Texture"},{"label":"Inlay Design","value":"4 Quad-Spaced Brushed Chrome Stainless Steel Horizontal Strips"},{"label":"Jamb & Architrave","value":"Complete Matching Casing with Sound-Dampening Rubber Gasket"},{"label":"Hardware Support","value":"Standard Mortise Magnetic Latch & Euro Profile Cylinder"},{"label":"Application","value":"Contemporary Luxury Residences, Hotels, Executive Boardrooms"}]'::jsonb, true, true),
('prd-door-05', 'classic-deep-walnut-flush-door-4-horizontal-silver-inlays', 'Classic Deep Walnut Flush Door with 4 Horizontal Silver Inlays', 'DOR-MHG-SLV4', 'cat-doors', 'Doors & Security Doors', 'doors', 'Timeless deep reddish-brown mahogany and walnut wood flush door with rich vertical grain figuring. Decorated with 4 clean horizontal silver aluminium strip accents and full matching mahogany wood casing.', 11000000, 9500000, 3, true, true, '["/products/classic-deep-walnut-flush-door-4-silver-inlays.jpg"]'::jsonb, 26, 0, 4, '[{"label":"Available Sizes","value":"800 x 2100mm, 800 x 2300mm, 900 x 2100mm, 900 x 2300mm, 1200 x 2100mm, 1200 x 2300mm"},{"label":"Finish","value":"High-Lustre Deep Walnut / Mahogany Wood Polish"},{"label":"Accents","value":"4 Horizontal Flush-Embedded Aluminium Inlays"},{"label":"Casing & Frame","value":"120mm - 150mm Adjustable Wall Thickness Door Jamb & Architraves"},{"label":"Core Construction","value":"Multi-Ply Engineered Wood Core for Anti-Warping Durability"},{"label":"Usage","value":"Luxury Residential Bedrooms, Bathrooms, Executive Suites"}]'::jsonb, true, false),
('prd-door-06', 'golden-honey-beech-flush-door-4-silver-chrome-inlays', 'Golden Honey Beech Flush Door with 4 Silver Chrome Inlays', 'DOR-BCH-SLV4', 'cat-doors', 'Doors & Security Doors', 'doors', 'Bright and welcoming golden honey beech interior door featuring natural wood warmth and 4 reflective silver chrome horizontal inlays. Supplied complete with matching honey beech architrave frame.', 10000000, 8800000, 3, true, true, '["/products/golden-honey-beech-flush-door-silver-inlays.jpg"]'::jsonb, 22, 0, 4, '[{"label":"Available Sizes","value":"800 x 2100mm, 800 x 2300mm, 900 x 2100mm, 900 x 2300mm, 1200 x 2100mm, 1200 x 2300mm"},{"label":"Tone & Finish","value":"Golden Honey Beech / Warm Teak Fine Grain"},{"label":"Inlays","value":"4 Stainless Chrome Horizontal Metallic Accent Strips"},{"label":"Architrave Frame","value":"Solid Timber Frame with Adjustable Architrave Lip Included"},{"label":"Moisture Resistance","value":"Treated Against Swelling, Termites, and Humid Environments"},{"label":"Recommended For","value":"Bedrooms, Hotel Guest Rooms, Corridors, Luxury Apartments"}]'::jsonb, true, false),
('prd-door-07', 'deep-walnut-architectural-door-3-stainless-steel-inlays-frame', 'Deep Walnut Architectural Door with 3 Stainless Steel Inlays & Frame', 'DOR-WLN-SS3', 'cat-doors', 'Doors & Security Doors', 'doors', 'Heavyweight dark American walnut finished door showing robust jamb construction. Features an architectural 3-strip inlay motif (2 upper header strips and 1 lower base strip) for a balanced modern look.', 12000000, 10500000, 3, true, true, '["/products/deep-walnut-rosewood-door-with-casing-frame.jpg"]'::jsonb, 18, 0, 3, '[{"label":"Available Sizes","value":"800 x 2100mm, 800 x 2300mm, 900 x 2100mm, 900 x 2300mm, 1200 x 2100mm, 1200 x 2300mm"},{"label":"Wood Figuring","value":"Rich Dark American Walnut with Straight & Swirl Grain Patterns"},{"label":"Inlay Pattern","value":"3 Stainless Steel Strips (2 Header Inlays, 1 Kickplate Inlay)"},{"label":"Door Frame","value":"Heavy-Duty Solid Engineered Wood Casing with Rebated Gasket"},{"label":"Leaf Thickness","value":"45mm Solid Security Standard Leaf"},{"label":"Application","value":"Apartment Entrance, Office Chambers, Master Bedroom"}]'::jsonb, true, true),
('prd-door-08', 'modern-warm-teak-flush-door-dual-silver-section-inlays', 'Modern Warm Teak Flush Door with Dual Silver Section Inlays', 'DOR-TEK-SLV2', 'cat-doors', 'Doors & Security Doors', 'doors', 'Natural warm teak interior door designed with two horizontal silver inlay lines that frame the handle and lock cylinder sector. Features full-height matching teak door frame and architraves.', 10200000, 8900000, 3, true, true, '["/products/modern-warm-teak-flush-door-dual-silver-inlays.jpg"]'::jsonb, 30, 0, 5, '[{"label":"Available Sizes","value":"800 x 2100mm, 800 x 2300mm, 900 x 2100mm, 900 x 2300mm, 1200 x 2100mm, 1200 x 2300mm"},{"label":"Finish","value":"Warm African Teak Semi-Gloss Wood Grain"},{"label":"Inlays","value":"Dual Horizontal Brushed Silver Strips Framing Lock Zone"},{"label":"Casing Package","value":"Includes 3-Piece Architrave Trim & Matching Rebated Jamb"},{"label":"Acoustic Rating","value":"Sound-Insulated Composite Core"},{"label":"Compatibility","value":"Standard Nigerian Mortise Locks and Ball-Bearing Hinges"}]'::jsonb, true, false),
('prd-door-09', 'modern-ebony-black-flush-door-dual-silver-accent-inlays', 'Modern Ebony Black Flush Door with Dual Silver Accent Inlays', 'DOR-EBN-SLV2', 'cat-doors', 'Doors & Security Doors', 'doors', 'High-contrast architectural interior flush door in rich ebony black grain finish. Accented by two horizontal silver inlays framing the chrome lockset zone, with matching black architrave frame casing.', 11000000, 9600000, 3, true, true, '["/products/modern-ebony-black-flush-door-dual-silver-inlays.jpg"]'::jsonb, 25, 0, 4, '[{"label":"Available Sizes","value":"800 x 2100mm, 800 x 2300mm, 900 x 2100mm, 900 x 2300mm, 1200 x 2100mm, 1200 x 2300mm"},{"label":"Finish","value":"Deep Ebony Black Matte Grain Finish"},{"label":"Accents","value":"Two Precision Horizontal Silver Metallic Strips"},{"label":"Casing System","value":"Full Ebony Black Architrave Jamb Set Included"},{"label":"Core Quality","value":"Solid Heavyweight Acoustic Core (45mm thickness)"},{"label":"Usage","value":"Luxury Minimalist Interiors, Master Suites, Studio Apartments"}]'::jsonb, true, true),
('prd-door-10', 'royal-armored-bulletproof-staggered-block-hardwood-entrance-door', 'Royal Armored Bulletproof Staggered-Block Hardwood Entrance Door', 'BLT-TEK-BLK10', 'cat-doors', 'Doors & Security Doors', 'doors', 'High-security armored bulletproof luxury entrance door featuring an interior ballistic steel core clad with staggered horizontal brick-motif solid natural teak hardwood. Fitted with multi-point anti-drill deadbolt locking system, heavy-gauge stainless steel vertical pull bar, and reinforced structural steel-reinforced door frame. Available in all standard and high-ceiling sizes.', 32000000, 28500000, 2, true, true, '["/products/solid-teak-block-panel-entrance-door.jpg"]'::jsonb, 15, 0, 3, '[{"label":"Security Rating","value":"Armored Ballistic Steel Core (Bulletproof Grade)"},{"label":"Available Sizes","value":"800 x 2100mm, 800 x 2300mm, 900 x 2100mm, 900 x 2300mm, 1200 x 2100mm, 1200 x 2300mm"},{"label":"Wood Facade","value":"Natural Solid African Teak Hardwood with UV Polyurethane Finish"},{"label":"Locking Mechanism","value":"Multi-Point Anti-Drill Security Mortise Deadbolts with Computer Keys"},{"label":"Hardware","value":"600mm Solid Stainless Steel Pull Bar & Lever Lockset Included"},{"label":"Frame & Casing","value":"Matching Heavy-Duty Steel-Reinforced Hardwood Jamb & Architrave Set"},{"label":"Application","value":"Main Luxury Entrance, VIP Residence, Executive Villa"}]'::jsonb, true, true),
('prd-door-11', 'executive-armored-bulletproof-7-plank-hardwood-door', 'Executive Armored Bulletproof 7-Plank Hardwood Security Door', 'BLT-HRD-7PLK11', 'cat-doors', 'Doors & Security Doors', 'doors', 'Architectural bulletproof security door built with a hardened steel armor plate core concealed beneath 7 wide horizontal solid hardwood planks. Offers maximum forced-entry protection and acoustic insulation, complemented with sleek matte black architectural hardware and full matching architrave casing. Available in all standard and high-ceiling sizes.', 28000000, 24500000, 2, true, true, '["/products/contemporary-7-plank-hardwood-door.jpg"]'::jsonb, 18, 0, 3, '[{"label":"Security Rating","value":"Reinforced Anti-Ballistic Steel Plate Core (Bulletproof)"},{"label":"Available Sizes","value":"800 x 2100mm, 800 x 2300mm, 900 x 2100mm, 900 x 2300mm, 1200 x 2100mm, 1200 x 2300mm"},{"label":"Wood Construction","value":"7 Horizontal Solid Hardwood Timber Planks with Arched Grain"},{"label":"Locking System","value":"High-Security Concealed Multi-Bolt Deadbolt System"},{"label":"Hardware","value":"Matte Black Architectural Lever Handle & Security Escutcheon Included"},{"label":"Frame Package","value":"Full Anti-Pry Structural Door Jamb & Matching Casing Trim"},{"label":"Application","value":"Master Suite, Luxury Bedroom, Private Office"}]'::jsonb, true, true),
('prd-door-12', 'grand-luxury-armored-bulletproof-vertical-groove-teak-door', 'Grand Luxury Armored Bulletproof Vertical-Groove Teak Entrance Door', 'BLT-GLD-VRT12', 'cat-doors', 'Doors & Security Doors', 'doors', 'Premier bulletproof armored entrance door featuring a high-impact ballistic core encased in seasoned vertical fluted golden teak timber. Outfitted with an oversized square stainless steel architectural pull handle, security optical viewer, multi-point lock cylinder, and high-strength reinforced sub-frame. Available in all standard and high-ceiling sizes.', 35000000, 31000000, 2, true, true, '["/products/architectural-golden-teak-vertical-door.jpg"]'::jsonb, 12, 0, 3, '[{"label":"Security Rating","value":"Heavy-Duty Armored Ballistic Steel Core (Bulletproof Grade)"},{"label":"Available Sizes","value":"800 x 2100mm, 800 x 2300mm, 900 x 2100mm, 900 x 2300mm, 1200 x 2100mm, 1200 x 2300mm"},{"label":"Timber Facing","value":"Seasoned Golden Teak Hardwood with Protective Clear Coat"},{"label":"Locking System","value":"Heavy-Duty Multi-Directional Security Deadbolts with Master Keys"},{"label":"Hardware","value":"Square-Profile Stainless Steel Pull Bar & Security Viewer Included"},{"label":"Frame & Casing","value":"Reinforced Anti-Intrusion Door Frame with Integrated Rubber Gasket"},{"label":"Application","value":"Grand Villa Entrance, Corporate Headquarters, Luxury Residence"}]'::jsonb, true, true)
